import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {World} from '../world.js';import {defaultHero} from '../mako.js';import {Battle,makeEnemy} from '../battle.js?v=5.6.0';
import {BOSS_GEAR,GEAR_ERAS,claimBossGear,gearStats,bossGearState,equipBossGear,unequipBossGear,syncBossGear,gearBonuses,gearDamage,inheritBossPatterns,reforgeInheritedGear,gearEra} from '../boss-gear.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));
const state=()=>({heroes:Array.from({length:7},(_,i)=>defaultHero(i,12)),recruited:[0,1,2,3,4,5,6],party:[0],chapter:12,bosses:[],mode:'field',gold:5000,story:{weapon:true}});
test('24 guardians expose 72 bounded historical forms for every companion',()=>{assert.equal(BOSS_GEAR.length,24);assert.equal(new Set(BOSS_GEAR.map(g=>g.id)).size,24);for(const id of [0,1,2,3,4,5,6]){const s=state(),h=s.heroes[id],base=structuredClone(h);for(const g of BOSS_GEAR){claimBossGear(s,g.chapter);for(const era of GEAR_ERAS){assert.ok(equipBossGear(s,id,g.id,era));for(const value of Object.values(gearStats(s,g,era)))assert.ok(Number.isFinite(value)&&value>=0);assert.ok(h.power<=base.power+18);assert.ok(h.magic<=base.magic+24);assert.ok(h.maxHp<=base.maxHp+144);assert.ok(h.maxMp<=base.maxMp+30);}}for(const slot of ['weapon','mantle','focus'])unequipBossGear(s,id,slot);for(const k of ['power','magic','maxHp','maxMp','speed'])assert.ok(Math.abs(h[k]-base[k])<1e-8,k);}});
test('unique ownership, battle locks, and one claim per history',()=>{const s=state();assert.ok(claimBossGear(s,1));assert.equal(claimBossGear(s,1),null);assert.ok(equipBossGear(s,0,'guardian-1'));assert.equal(equipBossGear(s,1,'guardian-1'),false);s.mode='battle';assert.equal(unequipBossGear(s,0,'weapon'),false);assert.equal(equipBossGear(s,0,'guardian-1','origin'),false);s.timeline={id:'another-life',era:'origin'};assert.ok(claimBossGear(s,1));assert.equal(bossGearState(s).owned.length,1);assert.equal(gearEra(s),'origin');s.timeline.era='invented';assert.equal(gearEra(s),'present');});
test('equipping, tempering and sync cannot heal or accumulate stats',()=>{const s=state(),h=s.heroes[0];claimBossGear(s,2);h.hp=11;h.mp=1;for(let i=0;i<100;i++){equipBossGear(s,0,'guardian-2',GEAR_ERAS[i%3]);syncBossGear(s);assert.equal(h.hp,11);assert.equal(h.mp,1);}assert.equal(h.maxHp,defaultHero(0,12).maxHp+gearBonuses(s,h).maxHp);});
test('new histories inherit discoveries, reforge locally, and suppress late-game raw power',()=>{const old=state(),next=state();for(const g of BOSS_GEAR)claimBossGear(old,g.chapter);next.chapter=1;next.timeline={id:'rook-before-the-fire',era:'origin'};inheritBossPatterns(old,next);assert.equal(bossGearState(next).patterns.length,24);assert.equal(bossGearState(next).owned.length,0);assert.equal(next.bosses.length,0);assert.equal(reforgeInheritedGear(next,'guardian-24'),false);next.chapter=6;const before=next.gold;assert.ok(reforgeInheritedGear(next,'guardian-24'));assert.equal(next.gold,before-160);assert.equal(reforgeInheritedGear(next,'guardian-24'),false);const low=gearStats(next,BOSS_GEAR[23],'present'),late=gearStats({...next,chapter:24},BOSS_GEAR[23],'present');assert.ok(low.magic<late.magic);assert.deepEqual(old.timeline,undefined);});
test('gear damage has bounded conditional synergy, resistance, and no secondary multiplication',()=>{const caster={guardianTraits:Array(8).fill({core:'flame',era:'present'})},target={status:{exposed:3},guardianTraits:Array(8).fill({core:'flame',era:'origin'})};assert.ok(Math.abs(gearDamage({},caster,target,100,{core:'flame'})-91.84)<1e-8);assert.equal(gearDamage({},caster,target,100,{core:'flame',secondary:true}),100);const e=makeEnemy('boss',1,0,true);e.x=3;e.y=3;const h=defaultHero(0,5);h.guardianTraits=[{core:'flame',era:'present'}];h.x=1;h.y=1;const b=new Battle({heroes:[h],enemies:[e]});b.damage(h,e,100,{core:'flame'});assert.equal(e.hp,e.maxHp-104);});
test('real boss rewards and gear survive World restore and level transitions without stacking',()=>{const w=new World(data);w.state.mode='field';w.state.recruited=[0,1,2];claimBossGear(w.state,1);equipBossGear(w.state,0,'guardian-1','origin');for(let n=1;n<=6;n++){const m=w.data.campaign.missions[n-1];w.state.chapter=n;w.currentBattle={mission:m,object:{type:'boss',bit:7},scene:w.scene.location};w.winBattle();w.state.mode='field';}assert.ok(bossGearState(w.state).owned.includes('guardian-6'));const saved=w.save(),copy=new World(data);copy.restore(saved);for(const k of ['maxHp','maxMp','power','magic','speed'])assert.ok(Math.abs(copy.state.heroes[0][k]-w.state.heroes[0][k])<1e-8,k);for(let i=0;i<20;i++)copy.restore(copy.save());assert.equal(copy.state.heroes[0].power,w.state.heroes[0].power);});
test('timeline armaments trade armor against health and survive battle snapshots',async()=>{const {applyBossEra}=await import('../boss-gear.js');for(let n=1;n<=24;n++)for(const era of GEAR_ERAS){const e=makeEnemy('boss',n,0,true),hp=e.maxHp,armor=e.maxArmor,power=e.power;applyBossEra(e,era);assert.ok(e.maxHp>=hp*.94&&e.maxHp<=hp*1.09);assert.ok(e.maxArmor<=armor*1.16);assert.ok(e.power<=power);const once=structuredClone(e);applyBossEra(e,era);assert.deepEqual(e,once);const h=defaultHero(0,12),b=new Battle({heroes:[h],enemies:[e],chapter:n,context:{tags:[],timeline:{id:'history-'+era,era}}});const saved=b.snapshot();b.restore(saved);assert.equal(b.enemies[0].gearEra,era);assert.equal(b.context.timeline.id,'history-'+era);}});
